package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MathUtils.binomialCoefficient.
 * Targeting branch and line coverage.
 */
public class MathUtils_binomialCoefficient_TriageGen5Test {

    @Test
    public void testBinomialCoefficient_BaseCases() {
        // (n == k) returns 1
        assertEquals(1L, MathUtils.binomialCoefficient(5, 5));
        assertEquals(1L, MathUtils.binomialCoefficient(0, 0));

        // (k == 0) returns 1
        assertEquals(1L, MathUtils.binomialCoefficient(5, 0));
        assertEquals(1L, MathUtils.binomialCoefficient(0, 0));

        // (k == 1) returns n
        assertEquals(5L, MathUtils.binomialCoefficient(5, 1));
        assertEquals(10L, MathUtils.binomialCoefficient(10, 1));

        // (k == n - 1) returns n
        assertEquals(5L, MathUtils.binomialCoefficient(5, 4));
        assertEquals(10L, MathUtils.binomialCoefficient(10, 9));
    }

    @Test
    public void testBinomialCoefficient_StandardValues() {
        // Standard combinations
        assertEquals(10L, MathUtils.binomialCoefficient(5, 2));
        assertEquals(10L, MathUtils.binomialCoefficient(5, 3));
        assertEquals(20L, MathUtils.binomialCoefficient(6, 3));
        assertEquals(120L, MathUtils.binomialCoefficient(10, 3));
    }

    @Test
    public void testBinomialCoefficient_LargeValues() {
        // Test values that are within Long range but large
        // 60 choose 30 is large but fits in long
        // C(60, 30) = 118264581564861424
        assertEquals(118264581564861424L, MathUtils.binomialCoefficient(60, 30));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testBinomialCoefficient_NLessThanK() {
        // n < k should throw IllegalArgumentException
        MathUtils.binomialCoefficient(5, 6);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testBinomialCoefficient_NNegative() {
        // n < 0 should throw IllegalArgumentException
        MathUtils.binomialCoefficient(-1, 0);
    }

    /**
     * Note: Testing the ArithmeticException for result == Long.MAX_VALUE 
     * depends on the internal implementation of binomialCoefficientDouble.
     * Since we cannot easily mock MathUtils, we target a known overflow case.
     */
    @Test(expected = ArithmeticException.class)
    public void testBinomialCoefficient_Overflow() {
        // A very large n and k that will exceed Long.MAX_VALUE
        // C(1000, 500) is astronomically large
        MathUtils.binomialCoefficient(1000, 500);
    }
}
